{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Gallopamil showed 96.3% oral bioavailability in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Vernakalant had absolute oral bioavailability of 58 ± 19% in fasted healthy volunteers after oral dosing versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Verapamil averaged 19.4% oral bioavailability in 20 normal young men after oral doses compared with IV, just below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transferability evidence from multiple molecules shows absolute oral bioavailability clearly above 20%, while one strong verapamil record is borderline low at 19.4%; the overall weight supports high bioavailability.",
  "evidence_gaps": [
    "Verapamil bioavailability is variable across studies, with values ranging from about 18% to 35%; the strongest record is 19.4%, just below threshold.",
    "Some records are qualitative or have unspecified bioavailability report types, limiting quantitative precision.",
    "Sustained-release verapamil data may not reflect ordinary immediate-release oral conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

